<script setup lang="ts">import {ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useAuthStore} from '@/stores/auth';import * as yup from 'yup';const auth=useAuthStore();const router=useRouter();const route=useRoute();const username=ref('emilys');const password=ref('emilyspass');const message=ref('');const schema=yup.object({username:yup.string().required(),password:yup.string().min(6).required()});async function submit(){message.value='';try{await schema.validate({username:username.value,password:password.value});await auth.login(username.value,password.value);router.push(String(route.query.redirect||'/users'))}catch(e){message.value=(e as Error).message}}</script>
<template><form class="card auth-card" @submit.prevent="submit"><div class="logo centered"><span>✦</span> Vue Lottery</div><h1>Вхід до кабінету</h1><p class="muted">Тест: emilys / emilyspass</p><label>Username<input v-model="username" autocomplete="username"/></label><label>Password<input v-model="password" type="password" autocomplete="current-password"/></label><p v-if="message" class="error">{{message}}</p><button class="button full">Увійти</button><RouterLink class="back" to="/">← На головну</RouterLink></form></template>
